/**
 * 备案申请Controller
- 
 * @author zhishu
 * @date 2023-06-01
 */
@Api(tags = "备案申请")
@RestController
@RequestMapping("/company/companyApply")
public class CompanyApplyController extends BaseController {

    @Autowired
    private CompanyApplyService companyApplyService;

    /**
     * 查询备案申请列表
     */
    @ApiOperation("查询备案申请列表")
    @RequiresPermissions(value = "company:companyApply:list")
    @PostMapping("/page")
    public PageResult<CompanyApplyVo> page(
            @RequestBody CompanyApplyPageQuery query) {
        IPage<CompanyApplyVo> page = companyApplyService.page(query.getPageNum, query.getPpageSize, query);
        return new PageResult<>(page);
    }

    /**
     * 获取备案申请详细信息
     */
    @ApiOperation("获取备案申请详细信息")
    @RequiresPermissions(value = "company:companyApply:query")
    @PostMapping("/detail")
    public JsonResult<CompanyApplyInfo> getByCompanyApplyId(
            @RequestBody Long companyApplyId) {
        return JsonResult.success(companyApplyService.getByCompanyApplyId(companyApplyId));
    }

    /**
     * 新增备案申请
     */
    @ApiOperation("新增备案申请")
    @RequiresPermissions(value = "company:companyApply:add")
    @Log(title = "备案申请", businessType = BusinessType.INSERT)
    @PostMapping("/add")
    public JsonResult<Long> add(@RequestBody @Validated(Insert.class) CompanyApplySaveInfo applyInfo) {
        Long id = companyApplyService.add(applyInfo);
        return JsonResult.success(id);
    }


    /**
     * 保存备案申请
     */
    @ApiOperation("保存备案申请")
    @RequiresPermissions(value = "company:companyApply:edit")
    @Log(title = "备案申请", businessType = BusinessType.UPDATE)
    @PostMapping(value = "/save")
    public JsonResult<Long> save(@RequestBody CompanyApplySaveInfo companyApply) {
        Long id = companyApplyService.saveOrUpdate(companyApply);
        return JsonResult.success(id);
    }

    /**
     * 修改备案申请
     */
    @ApiOperation("修改备案申请")
    @Log(title = "备案申请", businessType = BusinessType.UPDATE)
    @RequiresPermissions(value = "company:companyApply:edit")
    @PostMapping("/update")
    public JsonResult<Boolean> update(@RequestBody @Validated(Edit.class) CompanyApplySaveInfo companyApply) {
        return JsonResult.success(companyApplyService.update(companyApply));
    }

    /**
     * 删除备案申请
     */
    @ApiOperation("删除备案申请")
    @Log(title = "备案申请", businessType = BusinessType.DELETE)
    @RequiresPermissions(value = "company:companyApply:remove")
    @PostMapping("/delete")
    public JsonResult<Boolean> deleteByIds(@RequestBody List<Long> companyApplyIds) {
        return JsonResult.success(companyApplyService.deleteByIds(companyApplyIds));
    }

    /**
     * 提交备案申请
     */
    @ApiOperation("提交备案申请")
    @Log(title = "备案申请", businessType = BusinessType.UPDATE)
    @RequiresPermissions(value = "company:companyApply:submit")
    @PostMapping(value = "/submit")
    public JsonResult<Boolean> submit(@RequestBody @Validated SubmitInfoDto dto) {
        companyApplyService.submit(dto);
        return JsonResult.success(true);
    }

    /**
     * 审批备案申请
     */
    @ApiOperation("审批备案申请")
    @Log(title = "备案申请", businessType = BusinessType.UPDATE)
    @RequiresPermissions(value = "company:companyApply:approval")
    @PostMapping(value = "/approval")
    public JsonResult<Boolean> approval(@RequestBody ApprovalInfoDto dto) {
        companyApplyService.approval(dto);
        return JsonResult.success(true);
    }

}
